-- 2. Found items (posted_by is looked up by email so it works even if a user already existed)
INSERT INTO found_items (id, posted_by_user_id, title, description, category, location_found, date_found, status)
  SELECT 'c0000000-0000-4000-8000-000000000001', u.id, 'Samsung Galaxy A54 phone', 'Samsung Galaxy A54, Awesome Violet (light purple) colour, clear silicone case with a sticker of a mountain on the back. Screen has a small crack in the top-left corner. Phone is locked and was at about 40% battery. Handed in by cafeteria cleaning staff at 13:20. Stored in the Security Office safe, shelf A.', 'electronics', 'cafe-3 (Student Centre Cafeteria), table near the window', '2026-10-20', 'pending-verification' FROM users u WHERE u.email = 'peter.mwangi@strathmore.edu'
  ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, location_found = EXCLUDED.location_found, date_found = EXCLUDED.date_found, status = EXCLUDED.status, updated_at = now();
INSERT INTO found_items (id, posted_by_user_id, title, description, category, location_found, date_found, status)
  SELECT 'c0000000-0000-4000-8000-000000000002', u.id, 'HP EliteBook laptop charger', 'HP 65W laptop charger with blue-tip connector, black. The cable has white electrical tape wrapped near the brick and the initials ''J.K.'' written on the tape in marker. Found plugged into socket 14 at the silent study area. Stored at Security Office, drawer 2.', 'electronics', 'Library, 2nd Floor Front Desk', '2026-10-18', 'unclaimed' FROM users u WHERE u.email = 'faith.odhiambo@strathmore.edu'
  ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, location_found = EXCLUDED.location_found, date_found = EXCLUDED.date_found, status = EXCLUDED.status, updated_at = now();
INSERT INTO found_items (id, posted_by_user_id, title, description, category, location_found, date_found, status)
  SELECT 'c0000000-0000-4000-8000-000000000003', u.id, 'Strathmore student ID card', 'Strathmore University student ID card in a red lanyard with a plastic holder. Holder also contains a matatu SACCO loyalty card. Name and admission number visible on card (withheld here for privacy; claimant must state them). Found by the cashier after the lunch rush. Stored at Security Office, documents tray.', 'documents', 'cafe-1 (Main Cafeteria), payment counter', '2026-10-21', 'pending-verification' FROM users u WHERE u.email = 'joseph.rotich@strathmore.edu'
  ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, location_found = EXCLUDED.location_found, date_found = EXCLUDED.date_found, status = EXCLUDED.status, updated_at = now();
INSERT INTO found_items (id, posted_by_user_id, title, description, category, location_found, date_found, status)
